// Example from src/renderer/ipc/ipc-renderer.ts
import { ipcRenderer } from 'electron';

export function invoke(channel: string, ...args: any[]): Promise<any> {
  return ipcRenderer.invoke(channel, ...args);
}

export function send(channel: string, ...args: any[]): void {
  ipcRenderer.send(channel, ...args);
}

export function on(channel: string, listener: Function): () => void {
  const wrappedListener = (_event: any, ...args: any[]) => listener(...args);
  ipcRenderer.on(channel, wrappedListener);
  return () => ipcRenderer.removeListener(channel, wrappedListener);
}

// Example from src/renderer/ipc/api-client.ts
import { invoke, on } from './ipc-renderer';
import { IPC_CHANNELS } from '../../main/ipc/channel-names';

export async function startServer(): Promise<boolean> {
  const response = await invoke(IPC_CHANNELS.SERVER_START);
  return response.success ? response.data : false;
}

export async function getServerStatus(): Promise<ServerStatus> {
  const response = await invoke(IPC_CHANNELS.SERVER_STATUS);
  return response.success ? response.data : null;
}

export function onServerStatusChanged(callback: (status: ServerStatus) => void): () => void {
  return on(IPC_CHANNELS.SERVER_STATUS_CHANGED, callback);
}

// Example error handling in the main process
function handleIpcError(error: Error, channelName: string): IPCResponse {
  console.error(`Error in IPC channel ${channelName}:`, error);
  return {
    id: 'error',
    success: false,
    data: null,
    error: {
      code: error.code || ERROR_CODES.UNKNOWN_ERROR,
      message: error.message || 'An unknown error occurred',
      details: error.stack
    }
  };
}

// Example error handling in the renderer process
async function safeInvoke(channel: string, data?: any): Promise<any> {
  try {
    const response = await invoke(channel, data);
    if (response.success) {
      return response.data;
    } else {
      throw new Error(`${response.error.code}: ${response.error.message}`);
    }
  } catch (error) {
    console.error(`Error invoking ${channel}:`, error);
    throw error;
  }
}

// In a React component
import React, { useState, useEffect } from 'react';
import { startServer, stopServer, getServerStatus, onServerStatusChanged } from '../ipc/api-client';

function ServerControl() {
  const [status, setStatus] = useState({ isRunning: false });
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    // Get initial status
    getServerStatus().then(setStatus);

    // Subscribe to status changes
    const cleanup = onServerStatusChanged(setStatus);
    return cleanup;
  }, []);

  const handleStartServer = async () => {
    setIsLoading(true);
    try {
      await startServer();
    } catch (error) {
      console.error('Failed to start server:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleStopServer = async () => {
    setIsLoading(true);
    try {
      await stopServer();
    } catch (error) {
      console.error('Failed to stop server:', error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div>
      <h2>Server Status: {status.isRunning ? 'Running' : 'Stopped'}</h2>
      {status.isRunning ? (
        <button onClick={handleStopServer} disabled={isLoading}>Stop Server</button>
      ) : (
        <button onClick={handleStartServer} disabled={isLoading}>Start Server</button>
      )}
    </div>
  );
}

// In a React component
import React, { useState } from 'react';
import { generateClientConfig, generateQRCode } from '../ipc/api-client';
import QRCode from '../components/QRCode';

function ClientConfigGenerator() {
  const [clientName, setClientName] = useState('');
  const [config, setConfig] = useState(null);
  const [qrCode, setQRCode] = useState(null);
  const [isLoading, setIsLoading] = useState(false);

  const handleGenerateConfig = async () => {
    if (!clientName) return;

    setIsLoading(true);
    try {
      // Generate client configuration
      const newConfig = await generateClientConfig(clientName, {
        allowedIPs: ['0.0.0.0/0', '::/0'],
        persistentKeepalive: 25
      });
      setConfig(newConfig);

      // Generate QR code
      const qrData = await generateQRCode(newConfig.id);
      setQRCode(qrData);
    } catch (error) {
      console.error('Failed to generate configuration:', error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div>
      <h2>Generate Client Configuration</h2>
      <div>
        <label>
          Client Name:
          <input 
            type="text" 
            value={clientName} 
            onChange={(e) => setClientName(e.target.value)} 
          />
        </label>
        <button onClick={handleGenerateConfig} disabled={!clientName || isLoading}>
          Generate
        </button>
      </div>

      {qrCode && (
        <div>
          <h3>Scan this QR code with the WireGuard iOS app</h3>
          <QRCode data={qrCode} />
        </div>
      )}
    </div>
  );
}

// In a React component
import React, { useState, useEffect } from 'react';
import { getActiveConnections, disconnectClient, onClientConnected, onClientDisconnected, onConnectionStatsUpdate } from '../ipc/api-client';

function ConnectionMonitor() {
  const [connections, setConnections] = useState([]);

  useEffect(() => {
    // Get initial connections
    getActiveConnections().then(setConnections);

    // Subscribe to connection events
    const connectedCleanup = onClientConnected((client) => {
      setConnections(prev => [...prev, client]);
    });

    const disconnectedCleanup = onClientDisconnected(({ id }) => {
      setConnections(prev => prev.filter(client => client.id !== id));
    });

    const statsCleanup = onConnectionStatsUpdate(({ connections }) => {
      setConnections(connections);
    });

    return () => {
      connectedCleanup();
      disconnectedCleanup();
      statsCleanup();
    };
  }, []);

  const handleDisconnect = async (clientId) => {
    try {
      await disconnectClient(clientId);
    } catch (error) {
      console.error('Failed to disconnect client:', error);
    }
  };

  return (
    <div>
      <h2>Connected Clients ({connections.length})</h2>
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>IP Address</th>
            <th>Connected Since</th>
            <th>Data Transfer</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {connections.map(client => (
            <tr key={client.id}>
              <td>{client.name}</td>
              <td>{client.assignedIP}</td>
              <td>{new Date(client.connectedAt).toLocaleString()}</td>
              <td>
                ↑ {formatBytes(client.stats.bytesSent)}<br />
                ↓ {formatBytes(client.stats.bytesReceived)}
              </td>
              <td>
                <button onClick={() => handleDisconnect(client.id)}>
                  Disconnect
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function formatBytes(bytes) {
  if (bytes === 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
}
